"""Code generated by pyuic6: integration by composition and by multiple inheritance."""

import sys

from PyQt6.QtWidgets import QApplication, QWidget

from ui_well_data import Ui_WellData  # generated: pyuic6 c11_well_data.ui -o ...


class CompositionForm(QWidget):
    """Composition: the interface lives in self.ui (recommended)."""

    def __init__(self) -> None:
        super().__init__()
        self.ui = Ui_WellData()
        self.ui.setupUi(self)
        self.ui.buttons.accepted.connect(lambda: print("composition: OK"))


class InheritanceForm(QWidget, Ui_WellData):
    """Multiple inheritance: the widgets become direct attributes of self."""

    def __init__(self) -> None:
        super().__init__()
        self.setupUi(self)
        self.buttons.accepted.connect(lambda: print("inheritance: OK"))


if __name__ == "__main__":
    app = QApplication(sys.argv)
    a, b = CompositionForm(), InheritanceForm()
    a.ui.buttons.accepted.emit()
    b.buttons.accepted.emit()
    print("field via composition:", a.ui.nameField.objectName())
    print("field via inheritance:", b.nameField.objectName())
